"""CLDR-style plural-category selection for en, fr, ru, pl, ar.

Categories follow CLDR plural rules, restricted to non-negative integers.
"""


def _ru(n):
    n10 = n % 10
    n100 = n % 100
    if n10 == 1 and n100 != 11:
        return "one"
    if n10 in (2, 3, 4) and n100 not in (12, 13, 14):
        return "few"
    if n10 == 0 or n10 in (5, 6, 7, 8, 9) or n100 in (11, 12, 13, 14):
        return "many"
    return "other"


def _pl(n):
    n10 = n % 10
    n100 = n % 100
    if n == 1:
        return "one"
    if n10 in (2, 3, 4) and n100 not in (12, 13, 14):
        return "few"
    # For integers: everything else (including n == 0) is 'many'.
    return "many"


def _ar(n):
    if n == 0:
        return "zero"
    if n == 1:
        return "one"
    if n == 2:
        return "two"
    n100 = n % 100
    if 3 <= n100 <= 10:
        return "few"
    if 11 <= n100 <= 99:
        return "many"
    return "other"


_RULES = {
    "en": lambda n: "one" if n == 1 else "other",
    "fr": lambda n: "one" if n in (0, 1) else "other",
    "ru": _ru,
    "pl": _pl,
    "ar": _ar,
}


def category(lang, n):
    """Return the CLDR plural category for `lang` and non-negative integer `n`."""
    if lang not in _RULES:
        raise ValueError(f"unsupported language: {lang!r}")
    if not isinstance(n, int) or n < 0:
        raise ValueError(f"n must be a non-negative integer, got {n!r}")
    return _RULES[lang](n)


def plural(lang, n, forms_dict):
    """Pick the right form from forms_dict (keyed by category) for (lang, n).

    Raises KeyError naming the missing category if the needed form is absent.
    """
    cat = category(lang, n)
    try:
        return forms_dict[cat]
    except KeyError:
        raise KeyError(
            f"missing plural form for category {cat!r} "
            f"(lang={lang!r}, n={n}); available: {sorted(forms_dict)}"
        ) from None

