import pytest

from plural_rules import category, plural


# --- Independent re-derivation helpers (encoded directly from the rules) ---

def expected_ru(n):
    n10 = n % 10
    n100 = n % 100
    if n10 == 1 and n100 != 11:
        return "one"
    if 2 <= n10 <= 4 and n100 not in (12, 13, 14):
        return "few"
    if n10 == 0 or 5 <= n10 <= 9 or 11 <= n100 <= 14:
        return "many"
    return "other"


def expected_pl(n):
    n10 = n % 10
    n100 = n % 100
    if n == 1:
        return "one"
    if 2 <= n10 <= 4 and n100 not in (12, 13, 14):
        return "few"
    return "many"


def expected_ar(n):
    if n == 0:
        return "zero"
    if n == 1:
        return "one"
    if n == 2:
        return "two"
    n100 = n % 100
    if 3 <= n100 <= 10:
        return "few"
    if 11 <= n100 <= 99:
        return "many"
    return "other"


# --- ru: exhaustive over 0..130 ---

@pytest.mark.parametrize("n", range(131))
def test_ru_exhaustive(n):
    assert category("ru", n) == expected_ru(n)


# --- pl: exhaustive over 0..130 ---

@pytest.mark.parametrize("n", range(131))
def test_pl_exhaustive(n):
    assert category("pl", n) == expected_pl(n)


# --- ar: spot checks ---

@pytest.mark.parametrize(
    "n", [0, 1, 2, 3, 10, 11, 99, 100, 102, 103, 111, 200]
)
def test_ar_spot(n):
    assert category("ar", n) == expected_ar(n)


# --- en / fr: obvious small cases ---

@pytest.mark.parametrize(
    "n,cat",
    [(0, "other"), (1, "one"), (2, "other"), (5, "other"), (101, "other")],
)
def test_en(n, cat):
    assert category("en", n) == cat


@pytest.mark.parametrize(
    "n,cat",
    [(0, "one"), (1, "one"), (2, "other"), (5, "other"), (101, "other")],
)
def test_fr(n, cat):
    assert category("fr", n) == cat


# --- plural(): form picking and KeyError behaviour ---

def test_plural_picks_form():
    forms = {
        "zero": "ništa",
        "one": "knjigu",
        "two": "knjige",
        "few": "knjige",
        "many": "knjiga",
        "other": "knjiga",
    }
    assert plural("en", 1, {"one": "book", "other": "books"}) == "book"
    assert plural("en", 2, {"one": "book", "other": "books"}) == "books"
    assert plural("ar", 0, forms) == "ništa"
    assert plural("ar", 1, forms) == "knjigu"
    assert plural("ar", 2, forms) == "knjige"
    assert plural("ar", 5, forms) == "knjige"      # few (n%100 in 3-10)
    assert plural("ar", 11, forms) == "knjiga"     # many
    assert plural("ru", 21, forms) == "knjigu"     # one
    assert plural("ru", 22, forms) == "knjige"     # few
    assert plural("ru", 25, forms) == "knjiga"     # many
    assert plural("pl", 0, forms) == "knjiga"      # many


def test_plural_missing_form_raises_keyerror_naming_category():
    with pytest.raises(KeyError, match="few"):
        plural("ru", 2, {"one": "x", "other": "y"})


def test_unknown_lang_and_bad_n():
    with pytest.raises(ValueError):
        category("de", 1)
    with pytest.raises(ValueError):
        category("en", -1)

